<?php
require __DIR__.'/includes/bootstrap.php';$buyer=require_login('buyer');if($_SERVER['REQUEST_METHOD']!=='POST'){header('Location: /market.php');exit;}verify_csrf();
$productId=filter_var($_POST['product_id']??null,FILTER_VALIDATE_INT);$qty=filter_var($_POST['quantity']??null,FILTER_VALIDATE_FLOAT);$fulfillment=$_POST['fulfillment']??'pickup';$payment=$_POST['payment_method']??'to_agree';$note=trim($_POST['buyer_note']??'');
if(!$productId||!$qty||$qty<=0||!in_array($fulfillment,['pickup','delivery'],true)||!in_array($payment,['cash','bank_transfer','ewallet','to_agree'],true)||mb_strlen($note)>500){flash('Please check the order details and try again.','error');header('Location: /market.php');exit;}
try{$pdo->beginTransaction();$q=$pdo->prepare("SELECT * FROM products WHERE id=? AND status='active' FOR UPDATE");$q->execute([$productId]);$p=$q->fetch();if(!$p||$qty>(float)$p['quantity']||(int)$p['farmer_id']===(int)$buyer['id']){throw new RuntimeException('This product is unavailable or the quantity is no longer in stock.');}$total=round($qty*(float)$p['price'],2);$q=$pdo->prepare('INSERT INTO orders(buyer_id,farmer_id,product_id,quantity,unit_price,total,fulfillment,payment_method,buyer_note) VALUES(?,?,?,?,?,?,?,?,?)');$q->execute([$buyer['id'],$p['farmer_id'],$productId,$qty,$p['price'],$total,$fulfillment,$payment,$note?:null]);$left=(float)$p['quantity']-$qty;$q=$pdo->prepare("UPDATE products SET quantity=?,status=? WHERE id=?");$q->execute([$left,$left<=0?'sold_out':'active',$productId]);$pdo->commit();flash('Order request sent. You can check its status in My Orders.');header('Location: /orders.php');exit;}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();flash($e instanceof RuntimeException?$e->getMessage():'Could not send the order. Please try again.','error');header('Location: /product.php?id='.(int)$productId);exit;}
